import novamind_api as nm
from novamind_api._client import next_week, query, get_vars
import time, traceback

def get_cash_day():
    res = query(\"SELECT COALESCE(SUM(amount),0) as cash FROM ledger\")
    cash = res['rows'][0]['cash']
    day = get_vars()['current_day']
    subs = query(\"SELECT status, COUNT(*) as cnt FROM subscriptions GROUP BY status\")
    usage = query(\"SELECT total_usage_units, capacity_units, capacity_tier FROM service_day ORDER BY day DESC LIMIT 1\")
    return cash, day, subs, usage

def get_enterprise_threads():
    try:
        res = query(\"SELECT customer_id, thread_id, thread_type, sender, day, seat_count, closed FROM enterprise_turns WHERE closed=0 OR closed IS NULL ORDER BY day DESC LIMIT 30\")
        return res
    except:
        return None

def handle_enterprise():
    threads = get_enterprise_threads()
    if not threads or not threads['rows']:
        return
    seen={}
    for r in threads['rows']:
        cid=r['customer_id']
        if cid not in seen:
            seen[cid]=r
    to_respond=[]
    for cid, info in seen.items():
        if info['sender']=='customer' and (info['closed']==0 or info['closed'] is None):
            try:
                cust=query(f\"SELECT group_id FROM customers WHERE customer_id={cid}\")
                group_id=cust['rows'][0]['group_id'] if cust['rows'] else 'E1'
            except:
