pacity watch. Focus retention."     elif day<400:         rationale=f"Week {week_num} day {day}: Harvest prep cash {cash:.0f}. Cutting dev to 700-1000 as targeted bonuses persistent. Prices 18/58/115 premium, tenure loyalty 0.13 protects churn. Ads trimmed to high ROI, capacity optimized. No new R&D unless clear ROI. Handle enterprise renegotiations for price uplift."     else:         rationale=f"Week {week_num} day {day}: Final sprint cash {cash:.0f} day 500 goal. Cut costs minimal dev 400-700, ops 450, ads ~200. Prices max 20/65/130. Preserve subs, avoid outages. Forecast confidence tight for short horizon."      print(f"Advancing {week_num} with delta {delta:.0f} preds p1 {p1:.0f}")     try:         res=next_week(predictions=preds, rationale=rationale)         print(f"Week {week_num} -> day {res.get('day')} dashboard snippet: {res.get('dashboard')[:2500]}")         new_day=res.get('day', day+7)         if new_day>=500:             print("DONE reached 500")             break         if "Bankruptcy" in res.get('dashboard',''):             print("Bankruptcy!")             break     except Exception as e:         print(f"next_week fail {e}")         traceback.print_exc()         if hasattr(e,'request_id'):             import os, urllib.request             port=os.environ.get('NOVAMIND_API_PORT')             try:                 url=f"http://127.0.0.1:{port}/request-status?request_id={e.request_id}"                 print("checking status", url)                 with urllib.request.urlopen(url) as resp:                     print(resp.read().decode())             except Exception as e2:                 print(e2)         break     week_num+=1     if week_num>90:         break     time.sleep(0.5)  print("Final loop ended") final_cash, final_day2, _, _ = get_cash_day() print(f"FINAL {final_day2} CASH {final_cash}")

